<?php
require_once '../../config/database.php';require_once '../../config/helpers.php';require_role('admin');$id=(int)($_GET['id']??$_POST['id']??0);$stmt=mysqli_prepare($conn,"SELECT id,student_no,full_name,username FROM users WHERE id=? AND role='student'");mysqli_stmt_bind_param($stmt,'i',$id);mysqli_stmt_execute($stmt);$student=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));if(!$student){flash('Student record not found.','danger');header('Location: index.php');exit;}$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$no=trim($_POST['student_no']??'');$name=trim($_POST['full_name']??'');$username=trim($_POST['username']??'');$password=$_POST['password']??'';
if($no===''||$name===''||$username==='')$error='Complete all required fields.';
elseif($password!==''&&strlen($password)<8)$error='New password must contain at least 8 characters.';
else{if($password!==''){$hash=password_hash($password,PASSWORD_DEFAULT);$stmt=mysqli_prepare($conn,"UPDATE users SET student_no=?,full_name=?,username=?,password=? WHERE id=? AND role='student'");mysqli_stmt_bind_param($stmt,'ssssi',$no,$name,$username,$hash,$id);}else{$stmt=mysqli_prepare($conn,"UPDATE users SET student_no=?,full_name=?,username=? WHERE id=? AND role='student'");mysqli_stmt_bind_param($stmt,'sssi',$no,$name,$username,$id);}if(mysqli_stmt_execute($stmt)){flash('Student record updated.');header('Location: index.php');exit;}$error=mysqli_errno($conn)===1062?'Student number or username already exists.':'Could not update this student.';$student=array_merge($student,['student_no'=>$no,'full_name'=>$name,'username'=>$username]);}}
?>
